#include <vector>
using namespace std;

class Solution {
public:
    int countStudents(vector<int>& students, vector<int>& sandwiches) {
        int count[2] = {0, 0};
        for (int s : students) count[s]++;
        for (int s : sandwiches) {
            if (count[s] > 0) count[s]--;
            else break;
        }
        return count[0] + count[1];
    }
};

class Solution {
    public int countStudents(int[] students, int[] sandwiches) {
        int[] count = new int[2];
        for (int s : students) count[s]++;
        for (int s : sandwiches) {
            if (count[s] > 0) count[s]--;
            else break;
        }
        return count[0] + count[1];
    }
}

